 "0-1/lop-3-js.html": "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"chup\" content=\"560x300\">\n<title>Layer 3 — HTML + CSS + JavaScript</title>\n<style>\n  body   { font-family: system-ui, sans-serif; background: #f5f7fb; margin: 24px; }\n  h1     { color: #1f4e8c; margin: 0 0 4px; }\n  button { background: #1f4e8c; color: white; border: 0; border-radius: 8px;\n           padding: 10px 18px; font-size: 16px; cursor: pointer; }\n  #count { color: #555; }\n</style>\n</head>\n<body>\n  <h1>Hi, I'm Linh</h1>\n  <p>I am learning web development.</p>\n  <button id=\"like\">Like</button>\n  <p id=\"count\">0 likes</p>\n  <script>\n    let likes = 0;\n    const button = document.querySelector('#like');\n    const count = document.querySelector('#count');\n    button.addEventListener('click', () => {\n      likes = likes + 1;\n      count.textContent = likes + (likes === 1 ? ' like' : ' likes');\n      console.log('clicked, likes =', likes);\n    });\n    // the demo clicks three times by itself, so the screenshot shows the result\n    button.click(); button.click(); button.click();\n  </script>\n</body>\n</html>\n",
