 "_t1/git/out/env-mistake": "# the mistake: .env was committed BEFORE anyone wrote a .gitignore\n$ git commit -m \"First version\"\n[main (root-commit) 609f9a4] First version\n 2 files changed, 2 insertions(+)\n create mode 100644 .env\n create mode 100644 index.html\n$ echo '.env' > .gitignore\n$ echo 'API_KEY=dev-only-456' > .env\n$ git status --short\n M .env\n?? .gitignore\n# .gitignore does not stop tracking a file Git already tracks — untrack it:\n$ git rm --cached .env\nrm '.env'\n$ git add .gitignore\n$ git commit -m \"Stop tracking .env\"\n[main 2c7e7ce] Stop tracking .env\n 2 files changed, 1 insertion(+), 1 deletion(-)\n delete mode 100644 .env\n create mode 100644 .gitignore\n$ echo 'API_KEY=dev-only-789' > .env\n$ git status --short\n# …but the old value is still in history\n$ git log --oneline -- .env\n2c7e7ce Stop tracking .env\n609f9a4 First version\n$ git show HEAD~1:.env\nAPI_KEY=dev-only-123",
