 "_t6/out/headers": "$ curl -s -i http://localhost:3456/api/products/1\nHTTP/1.1 200 OK\nContent-Type: application/json; charset=utf-8\nETag: \"8c508e8ba06f\"\nCache-Control: no-cache\n\n{\"id\":1,\"name\":\"Notebook\",\"price\":25000,\"category\":\"office\"}\n\n$ curl -s -i http://localhost:3456/api/products/1 -H 'If-None-Match: \"8c508e8ba06f\"'\nHTTP/1.1 304 Not Modified\nETag: \"8c508e8ba06f\"\n\n\n$ curl -s -i 'http://localhost:3456/api/products?limit=3' -H 'Accept: text/csv'\nHTTP/1.1 200 OK\nContent-Type: text/csv; charset=utf-8\n\nid,name,price\n1,Notebook,25000\n2,Desk lamp,299000\n3,Pen,5000\n\n$ curl -s -i -X POST http://localhost:3456/api/products -H 'Content-Type: application/json' -d '{\"name\":\"Tape\",\"price\":15000}'\nHTTP/1.1 201 Created\nContent-Type: application/json; charset=utf-8\nLocation: /api/products/9\n\n{\"id\":9,\"name\":\"Tape\",\"price\":15000,\"category\":\"other\"}\n\n$ curl -s -i -X POST http://localhost:3456/api/products -d '{\"name\":\"Tape\",\"price\":15000}'\nHTTP/1.1 415 Unsupported Media Type\nContent-Type: application/json; charset=utf-8\n\n{\"error\":\"Send JSON\"}",
