 "_t6/out/query": "$ curl -s 'http://localhost:3456/api/products?category=office'\n{\"items\":[{\"id\":1,\"name\":\"Notebook\",\"price\":25000,\"category\":\"office\"},{\"id\":3,\"name\":\"Pen\",\"price\":5000,\"category\":\"office\"},{\"id\":5,\"name\":\"Stapler\",\"price\":45000,\"category\":\"office\"}],\"page\":1,\"limit\":10,\"total\":3}\n\n$ curl -s 'http://localhost:3456/api/products?category=office&sort=-price'\n{\"items\":[{\"id\":5,\"name\":\"Stapler\",\"price\":45000,\"category\":\"office\"},{\"id\":1,\"name\":\"Notebook\",\"price\":25000,\"category\":\"office\"},{\"id\":3,\"name\":\"Pen\",\"price\":5000,\"category\":\"office\"}],\"page\":1,\"limit\":10,\"total\":3}\n\n$ curl -s 'http://localhost:3456/api/products?page=2&limit=2'\n{\"items\":[{\"id\":3,\"name\":\"Pen\",\"price\":5000,\"category\":\"office\"},{\"id\":4,\"name\":\"Mug\",\"price\":60000,\"category\":\"home\"}],\"page\":2,\"limit\":2,\"total\":7}\n\n$ curl -s 'http://localhost:3456/api/products?q=desk%20lamp'\n{\"items\":[{\"id\":2,\"name\":\"Desk lamp\",\"price\":299000,\"category\":\"other\"}],\"page\":1,\"limit\":10,\"total\":1}\n\n$ curl -sS 'http://localhost:3456/api/products?q=desk lamp' 2>&1\ncurl: (3) URL rejected: Malformed input to a URL function\n\n$ curl -s http://localhost:3456/api/products/abc\n{\"error\":\"Product abc not found\"}\n\n$ curl -s 'http://localhost:3456/api/products?limit=abc'\n{\"items\":[],\"page\":1,\"limit\":null,\"total\":7}\n\n$ curl -s 'http://localhost:3456/api/products?limit=1000' | grep -o '\"limit\":[0-9]*'\n\"limit\":50",
