 "_t7/out/jwt-tay": "token  : eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJzdWIiOiIxIiwibmFtZSI6IkFuIiwicm9sZSI6InVzZXIiLCJpYXQiOjE3OTM2MDAwMDAsImV4cCI6MTc5MzYwMDkwMH0.pm_1On9_YHV3D91ZPFRlh-2qRvgxRCrlXTBsSK_5v0g\nlength : 176 characters (a session id was 43)\nheader : eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9\npayload: eyJzdWIiOiIxIiwibmFtZSI6IkFuIiwicm9sZSI6InVzZXIiLCJpYXQiOjE3OTM2MDAwMDAsImV4cCI6MTc5MzYwMDkwMH0\nsig    : pm_1On9_YHV3D91ZPFRlh-2qRvgxRCrlXTBsSK_5v0g\n\ndecoded payload, without the secret: {\"sub\":\"1\",\"name\":\"An\",\"role\":\"user\",\"iat\":1793600000,\"exp\":1793600900}\n\nverify(original)          → {\"ok\":true,\"payload\":{\"sub\":\"1\",\"name\":\"An\",\"role\":\"user\",\"iat\":1793600000,\"exp\":1793600900}}\nverify(role changed)      → {\"ok\":false,\"why\":\"bad signature\"}\nverify(alg: none)         → {\"ok\":false,\"why\":\"alg \\\"none\\\" refused\"}\nverify(16 minutes later)  → {\"ok\":false,\"why\":\"expired\"}\n\njsonwebtoken.sign gives the same string: true\njsonwebtoken.verify(original): {\"sub\":\"1\",\"name\":\"An\",\"role\":\"user\",\"iat\":1793600000,\"exp\":1793600900}\njsonwebtoken.verify(role changed): JsonWebTokenError: invalid signature\n\nGET /api/me (no Authorization header)          → 401 {\"error\":\"no token\"}\nGET /api/me  Bearer <token>                    → 200 {\"hello\":\"An\"}\nGET /api/me  Bearer <role changed>             → 401 {\"error\":\"bad signature\"}\nafter \"Log out\": a copied token, same request  → 200 {\"hello\":\"An\"}",
 "_t7/out/logout": "$ curl -s -b cookies.txt http://localhost:3457/api/me\n{\"id\":1,\"name\":\"An\",\"role\":\"user\"}\n\n$ curl -s -b cookies.txt -c cookies.txt -X POST http://localhost:3457/logout -i\nHTTP/1.1 200 OK\nContent-Type: application/json; charset=utf-8\nSet-Cookie: sid=; HttpOnly; Path=/; Max-Age=0\n\n{\"ok\":true}\n\n# the old cookie value, sent again by hand after logout:\n$ curl -s -i http://localhost:3457/api/me -H 'Cookie: sid=(the old value)'\nHTTP/1.1 401 Unauthorized\nContent-Type: application/json; charset=utf-8\n\n{\"error\":\"Log in first\"}",
 "_t7/out/mat-khau": "--- 1. sha256, no salt ---\nan@example.com     8d969eef6ecad3c29a3a6292…\nbinh@example.com   8d969eef6ecad3c29a3a6292…\nlan@example.com    7968449f48db07e60771cb51…\ncracked: an@example.com     → 123456\ncracked: binh@example.com   → 123456\ncracked: lan@example.com    → sunflower2009\n\n--- 2. sha256 with a salt per user ---\nan@example.com     salt bf5d2e7c44cd3a79 hash 5380ff7a3ba17f46416fa62d… | in table? false\nbinh@example.com   salt 458d6b2f7c4cf99c hash 79155aab7fe777e66118615a… | in table? false\n\n--- 3. how many guesses per second? (this laptop, one CPU core) ---\nsha256          : 1,917,183 hashes in 1 second\nbcrypt cost 10  : 75 ms per hash → 13.3 hashes per second\nbcrypt cost 12  : 278 ms per hash → 3.6 hashes per second\nscrypt (Node)   : 38 ms per hash\n\n--- 4. bcrypt: salt and cost are stored inside the hash ---\nhash #1: $2a$10$RFFthUmbL7xyCto/rg1Sh.6p0uzSWd.RJQT2xi3OoN.rCi0HnuKEe\nhash #2: $2a$10$RVIcMqSX0wuMdld/algJ3uicdyi8YX3emA2xEjwvu6dey9m8Tjvlq (same password, new salt)\nparts  : $2a$ = algorithm, 10$ = cost (2^10 rounds), next 22 chars = salt, last 31 = hash\ncompare(\"correct horse battery\", hash #1): true\ncompare(\"Correct horse battery\", hash #1): false",
 "_t7/out/session": "$ curl -s -i -X POST http://localhost:3457/login -H 'Content-Type: application/json' -d '{\"email\":\"an@example.com\",\"password\":\"wrong\"}'\nHTTP/1.1 401 Unauthorized\nContent-Type: application/json; charset=utf-8\n\n{\"error\":\"Wrong email or password\"}\n\n$ curl -s -i -X POST http://localhost:3457/login -H 'Content-Type: application/json' -d '{\"email\":\"nobody@example.com\",\"password\":\"x\"}'\nHTTP/1.1 401 Unauthorized\nContent-Type: application/json; charset=utf-8\n\n{\"error\":\"Wrong email or password\"}\n\n$ curl -s -i -c cookies.txt -X POST http://localhost:3457/login -H 'Content-Type: application/json' -d '{\"email\":\"an@example.com\",\"password\":\"correct horse battery\"}' | sed -E 's/sid=[A-Za-z0-9_-]{20,}/sid=(43 random characters)/'\nHTTP/1.1 200 OK\nContent-Type: application/json; charset=utf-8\nSet-Cookie: sid=(43 random characters); HttpOnly; SameSite=Lax; Path=/; Max-Age=3600\n\n{\"name\":\"An\"}\n\n$ curl -s -b cookies.txt http://localhost:3457/api/me\n{\"id\":1,\"name\":\"An\",\"role\":\"user\"}\n\n$ curl -s -i -b cookies.txt http://localhost:3457/api/admin/users\nHTTP/1.1 403 Forbidden\nContent-Type: application/json; charset=utf-8\n\n{\"error\":\"Admins only\"}",
 "_t8/out/aggregate": "sqlite> SELECT count(*) AS posts, sum(views) AS total_views, round(avg(views), 1) AS avg_views FROM posts WHERE published = 1;\n+-------+-------------+-----------+\n| posts | total_views | avg_views |\n+-------+-------------+-----------+\n|     4 |         545 |     136.3 |\n+-------+-------------+-----------+\n\nsqlite> SELECT user_id, count(*) AS posts, sum(views) AS views FROM posts GROUP BY user_id ORDER BY views DESC;\n+---------+-------+-------+\n| user_id | posts | views |\n+---------+-------+-------+\n|       2 |     2 |   303 |\n|       1 |     3 |   245 |\n|         |     1 |     0 |\n+---------+-------+-------+\n\nsqlite> SELECT user_id, count(*) AS posts FROM posts GROUP BY user_id HAVING count(*) >= 2;\n+---------+-------+\n| user_id | posts |\n+---------+-------+\n|       1 |     3 |\n|       2 |     2 |\n+---------+-------+",
 "_t8/out/cascade": "sqlite> SELECT (SELECT count(*) FROM posts) AS posts, (SELECT count(*) FROM comments) AS comments;\n+-------+----------+\n| posts | comments |\n+-------+----------+\n|     6 |        5 |\n+-------+----------+\n\nsqlite> DELETE FROM posts WHERE id = 1;\n\nsqlite> SELECT (SELECT count(*) FROM posts) AS posts, (SELECT count(*) FROM comments) AS comments;\n+-------+----------+\n| posts | comments |\n+-------+----------+\n|     5 |        3 |\n+-------+----------+\n\nsqlite> SELECT id, post_id, body FROM comments ORDER BY id;\n+----+---------+-----------------------------+\n| id | post_id |            body             |\n+----+---------+-----------------------------+\n|  3 |       4 | Very clear, thanks          |\n|  4 |       4 | Can you cover Express next? |\n|  5 |       2 | SQL finally makes sense     |\n+----+---------+-----------------------------+",
 "_t8/out/constraints": "sqlite> INSERT INTO users (name, email) VALUES ('Lan 2', 'lan@example.com');\nError near line 1: UNIQUE constraint failed: users.email\n\nsqlite> INSERT INTO users (name, email) VALUES (NULL, 'x@example.com');\nError near line 1: NOT NULL constraint failed: users.name\n\nsqlite> INSERT INTO posts (user_id, title, views, created_at) VALUES (1, 'Bad', -5, '2026-11-02');\nError near line 1: CHECK constraint failed: views >= 0\n\nsqlite> INSERT INTO posts (user_id, title, created_at) VALUES (99, 'Ghost author', '2026-11-02');\nError near line 1: FOREIGN KEY constraint failed\n\nsqlite> SELECT count(*) AS users, (SELECT count(*) FROM posts) AS posts FROM users;\n+-------+-------+\n| users | posts |\n+-------+-------+\n|     3 |     6 |\n+-------+-------+",
