 "_t8/out/many-to-many": "sqlite> CREATE TABLE tags (id INTEGER PRIMARY KEY, name TEXT NOT NULL UNIQUE);\nCREATE TABLE post_tags (\n  post_id INTEGER NOT NULL REFERENCES posts(id) ON DELETE CASCADE,\n  tag_id  INTEGER NOT NULL REFERENCES tags(id)  ON DELETE CASCADE,\n  PRIMARY KEY (post_id, tag_id)\n);\nINSERT INTO tags (id, name) VALUES (1, 'sql'), (2, 'beginner'), (3, 'node');\nINSERT INTO post_tags VALUES (1, 2), (2, 1), (2, 2), (4, 3), (4, 2);\n\nsqlite> SELECT p.title, group_concat(t.name, ', ') AS tags FROM posts p JOIN post_tags pt ON pt.post_id = p.id JOIN tags t ON t.id = pt.tag_id GROUP BY p.id ORDER BY p.id;\n+----------------+----------------+\n|     title      |      tags      |\n+----------------+----------------+\n| Hello World    | beginner       |\n| Learning SQL   | sql, beginner  |\n| Node.js Basics | node, beginner |\n+----------------+----------------+\n\nsqlite> SELECT t.name, count(*) AS posts FROM tags t JOIN post_tags pt ON pt.tag_id = t.id GROUP BY t.id ORDER BY posts DESC;\n+----------+-------+\n|   name   | posts |\n+----------+-------+\n| beginner |     3 |\n| node     |     1 |\n| sql      |     1 |\n+----------+-------+\n\nsqlite> INSERT INTO post_tags VALUES (2, 1);\nError near line 1: UNIQUE constraint failed: post_tags.post_id, post_tags.tag_id",
