 "_t8/out/prisma": "> prisma.post.findMany({ where: { published: true }, orderBy: { views: 'desc' }, take: 2, select: { title: true, views: true } })\n  SQL: SELECT Post.id, Post.title, Post.views FROM Post WHERE Post.published = ? ORDER BY Post.views DESC LIMIT ? OFFSET ?   params [true,2,0]\n  result: [{\"title\":\"Node.js Basics\",\"views\":300},{\"title\":\"Hello World\",\"views\":120}]\n\n> prisma.user.findUnique({ where: { email: 'minh@example.com' }, include: { posts: { select: { title: true } } } })\n  SQL: SELECT User.id, User.name, User.email FROM User WHERE (User.email = ? AND 1=1) LIMIT ? OFFSET ?   params [\"minh@example.com\",1,0]\n  SQL: SELECT Post.id, Post.title, Post.authorId FROM Post WHERE Post.authorId IN (?) LIMIT ? OFFSET ?   params [2,-1,0]\n  result: {\"id\":2,\"name\":\"Minh\",\"email\":\"minh@example.com\",\"posts\":[{\"title\":\"Draft Post\"},{\"title\":\"Node.js Basics\"}]}\n\n> prisma.post.create({ data: { title: 'My first post', author: { connect: { id: 1 } } } })\n  SQL: BEGIN IMMEDIATE \n  SQL: SELECT User.id FROM User WHERE (User.id = ? AND 1=1) LIMIT ? OFFSET ?   params [1,-1,0]\n  SQL: INSERT INTO Post (title, views, published, authorId) VALUES (?,?,?,?) RETURNING id AS id   params [\"My first post\",0,false,1]\n  SQL: SELECT Post.id, Post.title, Post.views, Post.published, Post.authorId FROM Post WHERE Post.id = ? LIMIT ? OFFSET ?   params [5,1,0]\n  SQL: COMMIT \n  result: {\"id\":5,\"title\":\"My first post\",\"views\":0,\"published\":false,\"authorId\":1}\n\n> prisma.user.create({ data: { name: 'Lan 2', email: 'lan@example.com' } })   — email already used\n  SQL: INSERT INTO User (name, email) VALUES (?,?) RETURNING id AS id, name AS name, email AS email   params [\"Lan 2\",\"lan@example.com\"]\n  threw: PrismaClientKnownRequestError P2002 — Unique constraint failed on the fields: (`email`)\n\n> prisma.post.update({ where: { id: 999 }, data: { views: 1 } })   — no such row\n  SQL: UPDATE Post SET views = ? WHERE (Post.id = ? AND 1=1) RETURNING id AS id, title AS title, views AS views, published AS published, authorId AS authorId   params [1,999]\n  threw: PrismaClientKnownRequestError P2025 — An operation failed because it depends on one or more records that were required but not found. Record to update not found.\n\n> prisma.$queryRaw`SELECT id, title FROM Post WHERE title LIKE ${search}`   — tagged template\n  SQL: SELECT id, title FROM Post WHERE title LIKE ?   params [\"%' OR 1=1 --\"]\n  result: []\n\n> prisma.$queryRawUnsafe(\"SELECT id, title FROM Post WHERE title LIKE '\" + search + \"'\")   — string gluing\n  SQL: SELECT id, title FROM Post WHERE title LIKE '%' OR 1=1 --' \n  result: [{\"id\":1,\"title\":\"Hello World\"},{\"id\":2,\"title\":\"Learning SQL\"},{\"id\":3,\"title\":\"Draft Post\"},{\"id\":4,\"title\":\"Node.js Basics\"},{\"id\":5,\"title\":\"My first post\"}]",
